SELECT a1.c0 AS c0, a1.c1 AS c1, a1.c2 AS c2, '{"k": -1, "a": [1, 2, 3]}'::jsonb AS c3 FROM (SELECT * FROM t0 WHERE EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 5e-324::float8 AS c1, '00:00:00.000001'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, 10.0::float8 AS c1, MIN ('0'::interval) OVER (PARTITION BY 16) AS c2 FROM v0 AS a1) AS kb) OR NOT EXISTS (SELECT 1 FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 100) SELECT []::text[] AS c0, 5e-324::float8 AS c1, '00:00:00.000001'::interval AS c2 UNION ALL SELECT ARRAY['1'::text] AS c0, 10.0::float8 AS c1, MIN ('0'::interval) OVER (PARTITION BY 16) AS c2 FROM v0 AS a1) AS kb)) AS a1 GROUP BY a1.c1, a1.c2, a1.c0 HAVING (a1.c2 IN (MAX (a1.c2)));
